//! Section controls operate on document planes, including inside editing contexts.
use crate::IngeTrazoApp;
#[derive(Clone)]pub enum SectionAction{Activate(uuid::Uuid),Deactivate,Reverse(uuid::Uuid),Delete(uuid::Uuid),Rename(uuid::Uuid,String,String),Display(bool,bool,bool)}
impl IngeTrazoApp{pub fn apply_section_action(&mut self,action:SectionAction){let mut candidate=self.scene.clone();match action{SectionAction::Display(cuts,planes,fill)=>{candidate.show_section_cuts=cuts;candidate.show_section_planes=planes;candidate.show_section_fill=fill;},SectionAction::Deactivate=>{for plane in &mut candidate.section_planes{plane.active=false;}},SectionAction::Activate(id)=>{if !candidate.section_planes.iter().any(|p|p.id==id){return;}for plane in &mut candidate.section_planes{plane.active=plane.id==id;}},SectionAction::Reverse(id)=>{let Some(plane)=candidate.section_planes.iter_mut().find(|p|p.id==id)else{return;};plane.flip();},SectionAction::Delete(id)=>candidate.section_planes.retain(|plane|plane.id!=id),SectionAction::Rename(id,name,symbol)=>{let Some(plane)=candidate.section_planes.iter_mut().find(|p|p.id==id)else{return;};plane.name=name;plane.symbol=symbol;}}if candidate!=self.scene{self.save_undo_state();candidate.bump_version();self.scene=candidate;}}
}
pub fn render_section_controls(app:&mut IngeTrazoApp,ui:&mut egui::Ui){let mut cuts=app.scene.show_section_cuts;let mut planes=app.scene.show_section_planes;let mut fill=app.scene.show_section_fill;let changed=ui.checkbox(&mut cuts,"Section Cuts").changed()|ui.checkbox(&mut planes,"Section Planes").changed()|ui.checkbox(&mut fill,"Section Fill").changed();if changed{app.apply_section_action(SectionAction::Display(cuts,planes,fill));}for plane in app.scene.section_planes.clone(){ui.menu_button(format!("{} {}",plane.symbol,plane.name),|ui|{if ui.selectable_label(plane.active,"Active Cut").clicked(){app.apply_section_action(if plane.active{SectionAction::Deactivate}else{SectionAction::Activate(plane.id)});}if ui.button("Reverse").clicked(){app.apply_section_action(SectionAction::Reverse(plane.id));}let draft_id=ui.id().with(plane.id);let(mut name,mut symbol)=ui.ctx().data_mut(|data|data.get_temp::<(String,String)>(draft_id)).unwrap_or((plane.name.clone(),plane.symbol.clone()));let a=ui.text_edit_singleline(&mut name);let b=ui.text_edit_singleline(&mut symbol);ui.ctx().data_mut(|data|data.insert_temp(draft_id,(name.clone(),symbol.clone())));if(a.lost_focus()||b.lost_focus())&&(name!=plane.name||symbol!=plane.symbol){app.apply_section_action(SectionAction::Rename(plane.id,name,symbol));ui.ctx().data_mut(|data|data.remove::<(String,String)>(draft_id));}if ui.button("Delete").clicked(){app.apply_section_action(SectionAction::Delete(plane.id));ui.close_menu();}});}}
#[cfg(test)]mod tests{use super::*;use glam::{DVec3,DMat4};use ingetrazo_core::{groups::Group,section::SectionPlane,scene::SelectionItem};#[test]fn sections_in_rotated_scaled_edit_context_keep_world_plane_and_outer_undo(){let mut app=IngeTrazoApp::new();let mut group=Group::new("part");group.transform=DMat4::from_translation(DVec3::new(1.,2.,3.))*DMat4::from_rotation_y(0.4)*DMat4::from_scale(DVec3::new(2.,3.,4.));app.scene.groups.push(group);app.scene.section_planes.push(SectionPlane::new(DVec3::new(2.,3.,4.),DVec3::new(1.,2.,3.),"section","A"));let before=app.scene.clone();let id=app.scene.section_planes[0].id;app.scene.select(SelectionItem::Group(0));app.begin_component_edit();app.apply_section_action(SectionAction::Reverse(id));app.finish_component_edit();assert_eq!(app.scene.section_planes[0].id,id);assert!((app.scene.section_planes[0].point-before.section_planes[0].point).length()<1e-10);assert!((app.scene.section_planes[0].normal+before.section_planes[0].normal).length()<1e-10);assert_eq!(app.undo_stack.len(),1);app.undo();assert_eq!(app.scene.section_planes,before.section_planes);}}

impl IngeTrazoApp{
 pub(crate) fn queue_section_name_prompt(&mut self){if self.document_session.preferences.extra.get("section_ask_name").and_then(|v|v.as_bool()).unwrap_or(true){if let Some(plane)=self.scene.section_planes.last(){self.section_name_prompt=Some((plane.id,plane.name.clone(),plane.symbol.clone(),false));}}}
 pub fn finish_section_name_prompt(&mut self,accepted:bool){let Some((id,name,symbol,no_more))=self.section_name_prompt.take()else{return;};if !accepted{return;}let Some(plane)=self.scene.section_planes.iter_mut().find(|p|p.id==id)else{return;};if !name.trim().is_empty(){plane.name=name.trim().to_owned();}if !symbol.trim().is_empty(){plane.symbol=symbol.trim().chars().take(3).collect();}self.scene.bump_version();if no_more{self.document_session.preferences.extra.insert("section_ask_name".into(),serde_json::json!(false));self.persist_preferences();}}
}
pub fn render_section_name_prompt(app:&mut IngeTrazoApp,ctx:&egui::Context){let mut accept=None;if let Some((id,name,symbol,no_more))=&mut app.section_name_prompt{if !app.scene.section_planes.iter().any(|plane|plane.id==*id){app.section_name_prompt=None;return;}egui::Window::new("Name Section Plane").collapsible(false).resizable(false).show(ctx,|ui|{ui.label("Name");ui.text_edit_singleline(name);ui.label("Symbol");ui.text_edit_singleline(symbol);ui.checkbox(no_more,"Don't ask again — keep defaults");ui.horizontal(|ui|{if ui.button("OK").clicked(){accept=Some(true);}if ui.button("Cancel").clicked(){accept=Some(false);}});});}if let Some(accepted)=accept{app.finish_section_name_prompt(accepted);}}

#[cfg(test)]mod prompt_tests{use super::*;use glam::DVec3;use ingetrazo_tools::base::{ToolType,ToolContext};use ingetrazo_core::math::Ray;
#[test]fn placement_prompt_cancel_rename_optout_and_undo_follow_original_history(){let mut app=IngeTrazoApp::new();app.set_tool(ToolType::SectionPlane);let context=ToolContext::new(DVec3::ZERO,Ray::new(DVec3::Z,-DVec3::Z));app.dispatch_tool_click(&context);assert!(app.section_name_prompt.is_some());assert_eq!(app.undo_stack.len(),1);app.finish_section_name_prompt(false);assert_eq!(app.scene.section_planes.len(),1);assert_eq!(app.undo_stack.len(),1);app.dispatch_tool_click(&context);let prompt=app.section_name_prompt.as_mut().unwrap();prompt.1=" New section ".into();prompt.2="ABCD".into();prompt.3=true;app.finish_section_name_prompt(true);assert_eq!(app.scene.section_planes[1].name,"New section");assert_eq!(app.scene.section_planes[1].symbol,"ABC");assert_eq!(app.undo_stack.len(),2);assert!(!app.scene.section_planes[0].active);app.undo();assert_eq!(app.scene.section_planes.len(),1);app.redo();assert_eq!(app.scene.section_planes[1].name,"New section");app.dispatch_tool_click(&context);assert!(app.section_name_prompt.is_none());}}
